!> Wraps `cdotc` as a subroutine.
!
! @param {integer} N - number of indexed elements
! @param {Array<complex>} cx - first array
! @param {integer} strideX - `cx` stride length
! @param {Array<complex>} cy - second array
! @param {integer} strideY - `cy` stride length
! @param {complex} dot - output variable reference
!<
subroutine cdotcsub( N, cx, strideX, cy, strideY, dot )
  implicit none
  ! ..
  ! External functions:
  interface
    complex function cdotc( N, cx, strideX, cy, strideY )
      complex, intent(in) :: cx(*), cy(*)
      integer :: strideX, strideY, N
    end function cdotc
  end interface
  ! ..
  ! Scalar arguments:
  integer :: strideX, strideY, N
  complex :: dot
  ! ..
  ! Array arguments:
  complex, intent(in) :: cx(*), cy(*)
  ! ..
  ! Compute the dot product:
  dot = cdotc( N, cx, strideX, cy, strideY )
  return
end subroutine cdotcsub
